__NUXT_JSONP__("/th", (function(a,b,c,d,e){return {data:[{$axios:{request:{},getUri:{},delete:{},get:{},head:{},options:{},post:{},put:{},patch:{},defaults:{headers:{common:{Accept:"application\u002Fjson, text\u002Fplain, *\u002F*","accept-encoding":"gzip, deflate"},delete:{},get:{},head:{},post:{"Content-Type":"application\u002Fx-www-form-urlencoded"},put:{"Content-Type":"application\u002Fx-www-form-urlencoded"},patch:{"Content-Type":"application\u002Fx-www-form-urlencoded"}},baseURL:"http:\u002F\u002Flocalhost:8000",transformRequest:[{}],transformResponse:[{}],timeout:0,adapter:{},xsrfCookieName:"XSRF-TOKEN",xsrfHeaderName:"X-XSRF-TOKEN",maxContentLength:-1,maxBodyLength:-1,validateStatus:{},transitional:{silentJSONParsing:true,forcedJSONParsing:true,clarifyTimeoutError:false}},interceptors:{request:{handlers:[{fulfilled:{},rejected:void 0,synchronous:false,runWhen:null}]},response:{handlers:[]}},CancelToken:{source:{}},isCancel:{},setBaseURL:{},setHeader:{},setToken:{},onRequest:{},onResponse:{},onRequestError:{},onResponseError:{},onError:{},create:{},$request:{},$delete:{},$get:{},$head:{},$options:{},$post:{},$put:{},$patch:{}},details:{slug:b,pageTitle:c,pageDescription:c,peopleChooseMli:{title:"3 เหตุผลที่ควรเลือก MLI",lists:[{image:"\u002Fimages\u002Fhome\u002Fth\u002Fpeople-choose-mli-1.jpg",title:"Hollywood & Westwood",description:"เราตั้งอยู่ใจกลางเมือง Los Angeles นอกจากการเรียนแล้ว นักเรียนยังสามารถเพลิดเพลินไปกับการท่องเที่ยวในเมือง Los Angeles อีกด้วย",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Fth\u002Fpeople-choose-mli-2.jpg",title:"ช่วงเช้า ช่วงบ่าย และช่วงเย็น",description:"เรามีหลากหลายช่วงเวลาให้เลือก สำหรับผู้ที่ต้องการตารางเรียนแบบปรับเปลี่ยนได้",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Fth\u002Fpeople-choose-mli-3.jpg",title:"$201 \u002F 1 สัปดาห์",description:"ทำเลดีและราคาที่เหมาะสมที่ท่านสามารถเทียบราคาแต่ละโรงเรียนได้ และหากท่านต้องการข้อมูลค่าเรียนเพิ่มเติม คลิก \"ติดต่อเรา\" ด้านล่าง",read_more:[a]}]},highlyRated:"\u002Fimages\u002Fhome\u002Fth\u002Fmli-highly-rated.jpg",courses:{title:"หลักสูตรสอนภาษา",lists:[{image:d,title:"หลักสูตรภาษาอังกฤษทั่วไป",subtitle:["หลักสูตรนี้ประกอบด้วย ทักษะการฟัง การพูด การอ่าน คำศัพท์ ไวยากรณ์และการเขียน ดังนั้น ESL จึงเหมาะสำหรับผู้ที่ต้องการฝึกทักษะทั่วไปทางด้านภาษา"]},{image:e,title:"หลักสูตร TOEFL®",subtitle:["TOEFL® เป็นโปรแกรมที่ฝึกทักษะและกลยุทธ์ที่จำเป็นอย่างละเอียดและเข้มข้น เพื่อให้ผู้เรียนผ่านการทดสอบทักษะภาษาอังกฤษทั้ง 4 ด้านของ Internet-Based Test (iBT)"]},{image:d,title:"Vacation ESL โปรแกรม",subtitle:["โปรแกรมนี้ประกอบด้วยชั้นเรียนการฟัง\u002Fการพูด การอ่าน\u002Fคำศัพท์ และไวยากรณ์\u002Fการเขียน \u003Cbr\u003Eเรามีโปรแกรม Vacation ESL สำหรับนักเรียนที่ต้องการเรียนภาษาอังกฤษระยะสั้น"]},{image:e,title:"IELTS™",subtitle:["IELTS ™เป็นการทดสอบที่พัฒนาขึ้นในสหราชอาณาจักรและออสเตรเลียเพื่อประเมินความสามารถทางภาษาอังกฤษของนักเรียน เมื่อเร็ว ๆ นี้มหาวิทยาลัยในอเมริกาจำนวนมากต้องการคะแนนTOEFL®หรือคะแนน IELTS ™","หลักสูตรนี้จะช่วยพัฒนาทักษะทั้ง 4 ด้าน คือ การฟัง การพูด การอ่านและการเขียน ผู้เรียนจะสามารถเรียนรู้ทักษะและกลยุทธ์เพื่อพิชิตคะแนนสอบในแต่ละส่วน","กล่าวได้ว่า IELTS ™ นั้นค่อนข้างง่ายกว่าTOEFL® เพราะเป็นหลักสูตรที่สมบูรณ์ สำหรับนักเรียนที่พบว่า TOEFL® นั้นยาก"]},{image:"\u002Fimages\u002Ficons\u002Fmessage.png",title:"โปรแกรมสนทนา",subtitle:["โปรแกรมของเราเน้นการเพิ่มทักษะการสนทนาภาษาอังกฤษของคุณผ่านกิจกรรมที่น่าสนใจและการเรียนรู้แบบแอ็กทิว! ในคลาสสนทนาของเรา นักเรียนจะได้สำรวจกำแพงคำศัพท์ วลี และสำนวนที่จะทำให้บทสนทนาของคุณมีชีวิตชีวาขึ้นมา ฝึกพูดออกเสียงในคลาส CMAR ผ่านการสนทนาสนุกๆ การเล่นบทบาท และกิจกรรมกลุ่ม คุณจะได้ความมั่นใจในการแสดงออกและการเข้าร่วมสนทนาที่มีความหมาย ผู้สอนที่มีประสบการณ์จะให้สนับสนุนในสภาพแวดล้อมการเรียนรู้และแนะนำคุณในการค้นพบภาษา"]},{image:"\u002Fimages\u002Ficons\u002Fsuitcase.png",title:"หลักสูตรภาษาอังกฤษเพื่อธุรกิจ + TOEIC®",subtitle:["การทดสอบ TOEIC®เป็นตัวบ่งชี้ความสามารถทางภาษาอังกฤษในธุรกิจและถูกใช้โดยบริษัท และองค์กรต่างๆทั่วโลก หลักสูตรธุรกิจและ หลักสูตรTOEIC® จะเตรียมความพร้อมให้ผู้เรียนประสบความสำเร็จในการสอบ TOEIC® โดยการสอบการฟังและการเขียน โดยการแนะนำคำศัพท์ที่จำเป็นและสำรวจกลยุทธ์ต่างๆ เพื่อให้ได้คะแนนสูงในการทดสอบ","หลักสูตรนี้จะเป็นประโยชน์ในการพัฒนาทักษะภาษาอังกฤษของท่าน เช่น คำศัพท์ การอ่าน การฟังและไวยากรณ์ โดยการเรียนรู้กลยุทธ์ในการหาคำตอบที่ถูกต้อง และท่านจะสามารถพิชิตคะแนนสูงสุดมาได้"]}]},schedule:"\u002Fimages\u002Fhome\u002Fen\u002Ffree_trial_banner-En.png",link:"\u002Fth\u002Ffreetrial",partnerSchools:{title:"MLI's Partner Universities \u002F Colleges",subtitle:"\"MLI students can enroll at partner universities or colleges after completing certain MLI programs.\""},locationCampus:{title:"สถานที่ตั้ง",lists:[{image:"\u002Fimages\u002Fhome\u002Flocation-campus-1.jpg",title:"สาขา Westwood",subtitle:"Westwood เป็นแหล่งที่น่าสนใจและเป็นเอกลักษณ์ ตั้งอยู่ทางฝั่งตะวันตกของ Los Angeles และมีชื่อเสียงจากการเป็นที่ตั้งของ UCLA เป็นพื้นที่ที่น่าค้นหาและเป็นที่นิยมสำหรับนักเรียน เพราะมีนักศึกษา ร้านค้า ร้านอาหารและสถานที่ปลอดภัยมากมายในการออกไปเที่ยว วิทยาเขตของเราตั้งอยู่ตรงข้ามกับพิพิธภัณฑ์ Hammer ซึ่งเป็นพิพิธภัณฑ์ศิลปะและศูนย์วัฒนธรรมที่มีชื่อเสียงระดับโลก",read_more:["\u003Ca href=\"\u002Fth\u002Fwestwood\u002F\"\u003E» อ่านเพิ่มเติม\u003C\u002Fa\u003E"]},{image:"\u002Fimages\u002Fhome\u002Flocation-campus-2.jpg",title:"สาขา Hollywood",subtitle:"สาขา Hollywood ตั้งอยู่บนถนนที่มีชื่อเสียงระดับโลกอย่างถนน Hollywood ใกล้กันนั้นมีโรงภาพยนตร์ที่มีชื่อเสียงโด่งดังมากมาย โดยเฉพาะโรงภาพยนตร์จีนที่มีชื่อเสียงเลื่องลือ รวมไปถึงร้านอาหาร ร้านค้าและแหล่งท่องเที่ยวต่างๆ บริเวณนี้เป็นสถานที่ที่มีความน่าสนใจมากอีกแห่งหนึ่ง",read_more:["\u003Ca href=\"\u002Fth\u002Fhollywood\u002F\"\u003E» อ่านเพิ่มเติม\u003C\u002Fa\u003E"]}]},testimonials:{title:"คำรับรองจากนักเรียน",seemoreBtn:"ดูเพิ่มเติม",TestimonialLink:"\u002Fth\u002Ftestimonials",readmoreBtn:"อ่านต่อ"},dir:"\u002Fhome",path:"\u002Fhome\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:29.613Z",updatedAt:"2025-05-26T12:06:27.786Z"},lang:b}],fetch:{},mutations:void 0}}("\u003Ca href=\"\u002Fth\u002Ffeature\u002F\"\u003E» อ่านเพิ่มเติม\u003C\u002Fa\u003E","th","โรงเรียนสอนภาษาอังกฤษราคาไม่แพงใน Los Angeles | Mentor Language Institute","\u002Fimages\u002Ficons\u002Fpaste.png","\u002Fimages\u002Ficons\u002Fpen.png")));